#!/usr/bin/env bash
# The SME re-sign utility (integrity batch 16, item 16.10; Codex round 15
# finding R15-P3-2, SME decision D16-4. List grammar and repository discovery
# rewritten in integrity batch 17 for Codex round 16 findings R16-P2-4 and
# R16-P2-5, SME decisions D17-1 and D17-2).
#
# WHAT THIS IS FOR. When a batch changes a reference file's bytes, every method
# manifest is regenerated by write_method_manifest(). Regeneration clears the
# root signature (reviewed_by / reviewed_at) and drops every unit of a drifted
# manifest back to `status: draft`, because the digests the SME signed no longer
# describe the file. Restoring the signature is the SME's act, not an agent's.
# This utility performs exactly that restoration from a reviewed input list, and
# nothing else.
#
# WHY IT IS A TRACKED FILE. Until integrity batch 16 the re-sign step was a
# per-batch script written into a scratchpad and thrown away, while CLAUDE.md
# described its live-tree guard as though it were a shipped control (Codex round
# 15, R15-P3-2). A fresh checkout could neither reuse nor test that guard, and
# the next batch could recreate an unguarded script while following the
# documentation. The utility and its guard are now reviewable and tested by
# tools/tests/test_sme_resign.sh.
#
# THE LIVE-TREE GUARD, AND WHY. On 2026-09-06 at about 04:50 UTC a rehearsal
# command ran the batch 15 sed script BEFORE its `cd` into the rehearsal copy,
# and signed the live manifest by accident. This utility therefore refuses to
# run when its working directory is the root of a git checkout unless --live is
# the FIRST argument.
#
# USAGE
#   tools/sme_resign.sh [--live] --reviewer <name> <list-file> <date>
#
# LIST FILE GRAMMAR (one directive per line; blank lines and lines whose FIRST
# non-blank character is `#` are ignored; a `#` anywhere else is a refusal, not
# a trailing comment):
#
#   digest <manifest-path> sha256:<64 hex>
#       The sha256 of that manifest as the SME reviewed it, BEFORE signing.
#       Every manifest named by a `root` or `appr` directive needs exactly one.
#       Nothing is rewritten unless the file on disk still hashes to this value.
#
#   digest-signed <manifest-path> sha256:<64 hex>
#       A NO-OP RECEIPT ONLY (SME decision D18-2). Written by this utility into
#       the list file after it signs a manifest for the first time, and read
#       back on a later run so that re-running the same list is a no-op instead
#       of a digest refusal. It authorises NOTHING: a run whose manifest matches
#       only this receipt is accepted only when every line the list addresses
#       already carries its target text. If anything would still be written, the
#       list was amended after signing, and it is refused until the SME reviews
#       a fresh pre-sign `digest` line. An SME does not write this line by hand.
#       At most one `digest` and one `digest-signed` line per manifest; a second
#       of either is a refusal naming both lines, not a last-one-wins override.
#
#   root <manifest-path>
#       Rewrite line 10 to the explicit `reviewed_by` value and line 11 to
#       `reviewed_at: "<date>"`. Both lines must currently be the empty-string
#       form written by regeneration.
#
#   appr <manifest-path> <unit-name>:<line> [<unit-name>:<line> ...]
#       Rewrite each named line to `    status: approved`. Each line must
#       currently be `    status: draft`, AND the nearest unit key above it
#       (a line of the form `  <name>:`) must be the unit named in the entry.
#
# WHY THE UNIT NAME AND THE DIGEST (SME decision D17-1, Codex round 16
# R16-P2-5). Line numbers are derived from a freshly regenerated manifest and
# reviewed by the SME as a list of numbers. If two equal-sized unit blocks
# exchange positions between the review and the run, the addressed line still
# reads `    status: draft` and the utility approves a unit the SME did not
# select. Both bindings close that: the digest refuses a manifest that changed
# at all after the review, and the unit key refuses an addressed line that has
# come to belong to another unit.
#
# ASSERT BEFORE REWRITE. Every line is compared with the exact text it is
# expected to carry before it is touched. A line that carries neither that text
# nor the text this utility would write is a REFUSAL naming the file and the
# line.
#
# IDEMPOTENT, AND WHAT THAT DOES NOT MEAN (corrected in integrity batch 18 for
# Codex round 17 R17-P2-6). A line that already carries the target text is
# SKIPPED rather than refused, so re-running an UNCHANGED list against an
# already-signed manifest is a no-op that exits 0.
#
# It is not a recovery procedure for an interrupted run. The writes happen
# first and the `digest-signed` receipt is appended last, so a run interrupted
# between a write and the receipt leaves a manifest whose bytes match NEITHER
# the pre-sign digest (it was partly rewritten) nor any receipt (none was
# written), and the next run refuses it. Recovery from that state is a
# regenerated manifest and a freshly reviewed list carrying a new pre-sign
# `digest` line -- an SME act, not a re-run.
#
# THIS UTILITY DOES NOT DECIDE ANYTHING. It does not choose which manifests or
# which units are signed; the list file carries the SME's decisions, and the
# drafts that stay drafts simply get no line. It never generates a manifest,
# never computes a manifest digest for the SME to review, and never approves a
# unit the list does not name.
set -eu

refuse() { echo "REFUSED: $1" >&2; exit 1; }

# THE LIVE-TREE GUARD, AND HOW IT DECIDES (integrity batch 16; rewritten in
# integrity batch 17 for Codex round 16 R16-P2-4 and SME decision D17-2).
#
# The question is "is the working directory the root of a git checkout?".
#
#   toplevel resolves and equals pwd       -> REFUSE (this is a checkout root)
#   toplevel resolves and differs          -> allow (a subdirectory; a
#                                             rehearsal copy under scratchpad/)
#   git says "not a git repository (or
#   any of the parent directories)", and
#   no GIT_DIR / GIT_WORK_TREE /
#   GIT_COMMON_DIR is set                  -> allow (a copy under a temp
#                                             directory: explicitly no checkout)
#   discovery fails while one of those
#   variables is set                       -> REFUSE, naming the variable
#   git unusable, or discovery FAILS for
#   any other reason                       -> REFUSE
#
# The last line is the batch 17 fix. Round 16 wrote
# `WD_ROOT="$(git rev-parse --show-toplevel 2>/dev/null || true)"`, which
# discards every failure alike. Git can print its version and still fail to
# identify the repository -- a broken worktree `.git` pointer, an ownership
# refusal, an inherited invalid GIT_DIR -- and an empty WD_ROOT was read as
# "not a checkout, proceed", in the live root. A guard that cannot evaluate its
# own condition refuses. `git --version` is kept as the first, cheapest check
# but is no longer the discriminator: the distinction is now made by git's own
# report about THIS directory.
#
# Rehearsal confinement stays working-directory-only (SME decision D17-2): this
# guard decides where the utility may run, not which paths it may write.
if [ "${1:-}" = "--live" ]; then
  shift
else
  if ! git --version >/dev/null 2>&1; then
    echo "REFUSED: git is not usable here, so the live-tree guard cannot decide" >&2
    echo "         whether this working directory ($(pwd -P)) is the live" >&2
    echo "         repository. It refuses rather than proceed. Pass --live as the" >&2
    echo "         FIRST argument only with the SME's word." >&2
    exit 2
  fi
  set +e
  GIT_OUT="$(git rev-parse --show-toplevel 2>&1)"
  GIT_RC=$?
  set -e
  if [ "$GIT_RC" -eq 0 ]; then
    WD_ROOT="$(cd "$GIT_OUT" && pwd -P)"
    if [ "$(pwd -P)" = "$WD_ROOT" ]; then
      echo "REFUSED: the working directory is the root of a git checkout ($WD_ROOT)." >&2
      echo "         Signing there requires --live as the FIRST argument (the SME's word);" >&2
      echo "         a rehearsal runs after a cd into a disposable copy." >&2
      exit 2
    fi
  else
    set +e
    INSIDE="$(git rev-parse --is-inside-work-tree 2>/dev/null)"
    set -e
    # AN INHERITED ROUTING VARIABLE IS NOT AN ORDINARY REHEARSAL (Codex round 17
    # R17-P2-4, integrity batch 18). `GIT_DIR=/nonexistent git rev-parse
    # --show-toplevel` fails with "fatal: not a git repository:
    # '/nonexistent'". Batch 17 accepted ANY diagnostic containing "not a git
    # repository" as proof that this directory is in no work tree, so an
    # invalid GIT_DIR, GIT_WORK_TREE or GIT_COMMON_DIR inherited from the
    # environment made the guard permit the run -- in the live root as readily
    # as anywhere else. When any of those variables is set and discovery
    # failed, the guard cannot tell what it was pointed at, so it refuses and
    # names the variable. The rehearsal case is now only the plain "no
    # repository here" form, or --is-inside-work-tree explicitly saying false.
    ROUTED=""
    if [ -n "${GIT_DIR:-}" ]; then ROUTED="GIT_DIR"
    elif [ -n "${GIT_WORK_TREE:-}" ]; then ROUTED="GIT_WORK_TREE"
    elif [ -n "${GIT_COMMON_DIR:-}" ]; then ROUTED="GIT_COMMON_DIR"
    fi
    if [ -n "$ROUTED" ]; then
      echo "REFUSED: repository discovery failed while $ROUTED is set in the" >&2
      echo "         environment ($ROUTED=${!ROUTED}); git reported:" >&2
      echo "         $GIT_OUT" >&2
      echo "         An inherited routing variable that does not resolve is not" >&2
      echo "         evidence that this working directory ($(pwd -P)) is a" >&2
      echo "         disposable copy. Unset it and run again from the copy." >&2
      exit 2
    fi
    if [ "$INSIDE" = "false" ] || \
       printf '%s' "$GIT_OUT" | grep -qiF 'not a git repository (or any of the parent directories)'; then
      : # explicitly established: this directory is in no work tree. A rehearsal.
    else
      echo "REFUSED: git works but could not identify the repository for this" >&2
      echo "         working directory ($(pwd -P)); it reported:" >&2
      echo "         $GIT_OUT" >&2
      echo "         A failed discovery is not evidence that this is a disposable" >&2
      echo "         copy, so the live-tree guard refuses. Pass --live as the FIRST" >&2
      echo "         argument only with the SME's word." >&2
      exit 2
    fi
  fi
fi

if [ "${1:-}" != "--reviewer" ] || [ "$#" -lt 2 ]; then
  refuse 'Usage: sme_resign.sh [--live] --reviewer <name> <list-file> <date>'
fi
REVIEWER="$2"
shift 2
if [[ "$REVIEWER" == *$'\n'* || "$REVIEWER" == *$'\r'* ]] ||
   ! printf '%s\n' "$REVIEWER" | LC_ALL=C.UTF-8 grep -Pq '[^\h\v]'; then
  refuse 'reviewer must be one non-empty line.'
fi
if printf '%s\n' "$REVIEWER" | LC_ALL=C.UTF-8 grep -Piq '^[\h\v]*(the[\h\v]+)?sme[\h\v]*$'; then
  refuse 'reviewer uses a reserved role label. Enter the local reviewer name.'
fi
# Quoted manifest scalars must agree in the R reader and YAML parser.
if [[ "$REVIEWER" == *[\"\\#[:cntrl:]]* ]]; then
  refuse 'reviewer contains a character unsupported in a manifest scalar.'
fi
if [ "$#" -gt 2 ]; then
  refuse 'Usage: sme_resign.sh [--live] --reviewer <name> <list-file> <date>'
fi

LIST="${1:-}"
DATE="${2:-}"
if [ -z "$LIST" ]; then
  echo "REFUSED: no list file given. Usage: sme_resign.sh [--live] --reviewer <name> <list-file> <date>" >&2
  exit 2
fi
if [ ! -f "$LIST" ]; then
  echo "REFUSED: the list file '$LIST' does not exist." >&2
  exit 2
fi
if [ -z "$DATE" ]; then
  echo "REFUSED: no date given. Usage: sme_resign.sh [--live] --reviewer <name> <list-file> <date>" >&2
  exit 2
fi
# THE DATE IS WRITTEN INTO A sed REPLACEMENT (Codex round 16 R16-P2-5), so its
# SHAPE is checked before it can reach one: four digits, a dash, two digits, a
# dash, two digits, and nothing else. The year must be 1000 or later: R's
# format() does not zero-pad years below 1000, so tools/method_manifest.R's
# round-trip check refuses "0026-09-06" even though it is a real date, and
# this utility must not write a date that reader cannot read (found by the
# batch 18 review).
case "$DATE" in
  [1-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]) : ;;
  *) echo "REFUSED: the date '$DATE' is not YYYY-MM-DD with a year of 1000 or later." >&2; exit 2 ;;
esac
# AND THEN THAT IT IS A REAL CALENDAR DATE (Codex round 17 R17-P2-5, integrity
# batch 18). The shape check alone accepted 2026-02-30, 2026-13-01 and
# 2025-02-29, which this utility would write into `reviewed_at:` and
# tools/method_manifest.R would then refuse to read (it parses the date and
# requires a formatting round trip), leaving a manifest that no longer loads.
# `date -u -d "$DATE" +%F` is the check here: GNU date rejects an impossible
# day outright, and a date it silently normalised would print something other
# than "$DATE". It agrees with the manifest reader's round trip for every year
# from 1000 on; the year floor in the shape check above covers the years where
# the two would disagree.
if [ "$(date -u -d "$DATE" +%F 2>/dev/null)" != "$DATE" ]; then
  echo "REFUSED: the date '$DATE' has the right shape but is not a real calendar" >&2
  echo "         date (check the month and the day; 2024-02-29 exists, 2025-02-29" >&2
  echo "         does not)." >&2
  exit 2
fi

ROOT_BY_TARGET="reviewed_by: \"$REVIEWER\""
ROOT_BY_REPLACEMENT="$(printf '%s' "$ROOT_BY_TARGET" | sed 's/[&|]/\\&/g')"
ROOT_AT_TARGET="reviewed_at: \"$DATE\""
ROOT_BY_EXPECT='reviewed_by: ""'
ROOT_AT_EXPECT='reviewed_at: ""'
UNIT_TARGET='    status: approved'
UNIT_EXPECT='    status: draft'

n_root=0
n_unit=0

line_is() { [ "$(sed -n "${2}p" "$1")" = "$3" ]; }

sha_of() {
  local s
  s="$(sha256sum "$1")" || refuse "could not hash $1."
  printf 'sha256:%s' "${s%% *}"
}

# The nearest unit key at or above the addressed line: a line written exactly
# `  <name>:` with nothing after the colon.
unit_key_above() {
  local f="$1" n="$2" hit
  hit="$(sed -n "1,$((n - 1))p" "$f" | grep -n '^  [A-Za-z0-9_][A-Za-z0-9_]*:$' | tail -n 1)"
  [ -n "$hit" ] || return 1
  hit="${hit#*:}"          # drop grep's line number
  hit="${hit#  }"          # drop the two-space indent
  printf '%s' "${hit%:}"
}

# --- pass 1: read the list -------------------------------------------------
declare -a DIG_PATH=() DIG_SHA=() DIG_LINE=() SIG_PATH=() SIG_SHA=() SIG_LINE=()
declare -a ROOT_PATH=() APPR_PATH=() APPR_UNIT=() APPR_LINE=()

lineno=0
while IFS= read -r raw || [ -n "$raw" ]; do
  lineno=$((lineno + 1))
  line="${raw#"${raw%%[![:space:]]*}"}"
  line="${line%"${line##*[![:space:]]}"}"
  [ -n "$line" ] || continue
  case "$line" in '#'*) continue ;; esac
  # NO TRAILING COMMENTS (Codex round 16 R16-P2-5). The documented grammar has
  # full-line comments only; round 16 nevertheless stripped from the first `#`
  # anywhere, so a `#` inside a path silently truncated a directive.
  case "$line" in *'#'*) refuse "$LIST:$lineno carries a '#' that is not a full-line comment: $line" ;; esac
  # `read -ra` splits on whitespace and performs NO pathname expansion, unlike
  # the `set -- $line` this replaces (Codex round 16 R16-P2-5).
  read -ra F <<<"$line"
  kind="${F[0]}"
  case "$kind" in
    digest|digest-signed)
      [ "${#F[@]}" -eq 3 ] || refuse "$LIST:$lineno: a '$kind' directive takes a manifest path and one sha256:<hex>: $line"
      case "${F[2]}" in
        sha256:[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]) : ;;
        *) refuse "$LIST:$lineno: '${F[2]}' is not sha256:<64 lowercase hex>." ;;
      esac
      # AT MOST ONE OF EACH KIND PER MANIFEST (Codex round 17 R17-P2-6,
      # integrity batch 18). Round 17's lookup kept the LAST matching line, so a
      # concatenated or hand-amended list naming one manifest with two different
      # `digest` values ran silently against whichever came last. Which of the
      # two the SME reviewed is not knowable from the file, so both are named
      # and nothing is rewritten.
      if [ "$kind" = "digest" ]; then
        for j in "${!DIG_PATH[@]}"; do
          [ "${DIG_PATH[$j]}" = "${F[1]}" ] && \
            refuse "$LIST names '${F[1]}' with two 'digest' directives (line ${DIG_LINE[$j]} and line $lineno). Exactly one pre-sign digest per manifest; nothing was rewritten."
        done
        DIG_PATH+=("${F[1]}"); DIG_SHA+=("${F[2]}"); DIG_LINE+=("$lineno")
      else
        for j in "${!SIG_PATH[@]}"; do
          [ "${SIG_PATH[$j]}" = "${F[1]}" ] && \
            refuse "$LIST names '${F[1]}' with two 'digest-signed' directives (line ${SIG_LINE[$j]} and line $lineno). This utility writes at most one receipt per manifest; nothing was rewritten."
        done
        SIG_PATH+=("${F[1]}"); SIG_SHA+=("${F[2]}"); SIG_LINE+=("$lineno")
      fi
      ;;
    root)
      [ "${#F[@]}" -eq 2 ] || refuse "$LIST:$lineno: a 'root' directive takes exactly one manifest path: $line"
      ROOT_PATH+=("${F[1]}")
      ;;
    appr)
      [ "${#F[@]}" -ge 3 ] || refuse "$LIST:$lineno: an 'appr' directive takes a manifest path and at least one <unit>:<line>: $line"
      i=2
      while [ "$i" -lt "${#F[@]}" ]; do
        entry="${F[$i]}"
        case "$entry" in
          *:*) : ;;
          *) refuse "$LIST:$lineno: '$entry' is not <unit-name>:<line> (SME decision D17-1)." ;;
        esac
        u="${entry%:*}"; ln="${entry##*:}"
        case "$ln" in ''|*[!0-9]*) refuse "$LIST:$lineno: '$entry' does not end in a line number." ;; esac
        [ -n "$u" ] || refuse "$LIST:$lineno: '$entry' names no unit."
        APPR_PATH+=("${F[1]}"); APPR_UNIT+=("$u"); APPR_LINE+=("$ln")
        i=$((i + 1))
      done
      ;;
    *)
      refuse "unknown directive '$kind' in $LIST:$lineno. The grammar is 'digest <manifest> sha256:<hex>', 'root <manifest>' and 'appr <manifest> <unit>:<line>...'."
      ;;
  esac
done < "$LIST"

# --- pass 2: validate, writing nothing -------------------------------------
declare -a TOUCHED=()
note_touched() {
  local p="$1" t
  for t in "${TOUCHED[@]}"; do [ "$t" = "$p" ] && return 0; done
  TOUCHED+=("$p")
}
for p in "${ROOT_PATH[@]}"; do note_touched "$p"; done
for p in "${APPR_PATH[@]}"; do note_touched "$p"; done

recorded_for() {          # array-name-free lookup: $1 = path, $2 = "pre"|"post"
  local p="$1" want="$2" i out=""
  if [ "$want" = "pre" ]; then
    for i in "${!DIG_PATH[@]}"; do [ "${DIG_PATH[$i]}" = "$p" ] && out="${DIG_SHA[$i]}"; done
  else
    for i in "${!SIG_PATH[@]}"; do [ "${SIG_PATH[$i]}" = "$p" ] && out="${SIG_SHA[$i]}"; done
  fi
  printf '%s' "$out"
}

for p in "${TOUCHED[@]}"; do
  [ -f "$p" ] || refuse "$p does not exist (named by the list)."
  pre="$(recorded_for "$p" pre)"
  [ -n "$pre" ] || refuse "$p is signed by this list but the list records no 'digest $p sha256:<hex>' line (SME decision D17-1)."
  post="$(recorded_for "$p" post)"
  cur="$(sha_of "$p")"
  if [ "$cur" = "$pre" ]; then continue; fi
  if [ -z "$post" ] || [ "$cur" != "$post" ]; then
    refuse "$p has changed since the SME reviewed this list (list records $pre, on disk $cur). Regenerate the list and have it reviewed again; nothing was rewritten."
  fi
  # THE RECEIPT IS A NO-OP RECEIPT ONLY (SME decision D18-2, Codex round 17
  # R17-P2-6). The manifest matches the post-sign digest, so this list has
  # already been run against these bytes. That is a reason to skip the work, not
  # a licence to do NEW work: round 17 accepted the receipt and then rewrote
  # whatever the list addressed, so appending an `appr` for a second unit and
  # re-running approved that unit under a digest no SME ever reviewed. Every
  # line this list addresses in $p must therefore already carry its target text.
  # The same line_is checks the write loop uses decide it.
  pending=""
  for i in "${!ROOT_PATH[@]}"; do
    [ "${ROOT_PATH[$i]}" = "$p" ] || continue
    if ! (line_is "$p" 10 "$ROOT_BY_TARGET" && line_is "$p" 11 "$ROOT_AT_TARGET"); then
      pending="the root signature block (lines 10-11)"
    fi
  done
  for i in "${!APPR_PATH[@]}"; do
    [ "${APPR_PATH[$i]}" = "$p" ] || continue
    line_is "$p" "${APPR_LINE[$i]}" "$UNIT_TARGET" || \
      pending="${APPR_UNIT[$i]}:${APPR_LINE[$i]}"
  done
  if [ -n "$pending" ]; then
    refuse "$p already carries the signature this list recorded ($post), but the list still asks for a change that has not been made ($pending). The list was amended after it was signed; a 'digest-signed' receipt authorises no new work. Have a freshly generated list with a new reviewed 'digest' line; nothing was rewritten."
  fi
done

for i in "${!ROOT_PATH[@]}"; do
  f="${ROOT_PATH[$i]}"
  if ! (line_is "$f" 10 "$ROOT_BY_TARGET" && line_is "$f" 11 "$ROOT_AT_TARGET"); then
    line_is "$f" 10 "$ROOT_BY_EXPECT" || \
      refuse "$f:10 is not '$ROOT_BY_EXPECT' (it reads '$(sed -n 10p "$f")')."
    line_is "$f" 11 "$ROOT_AT_EXPECT" || \
      refuse "$f:11 is not '$ROOT_AT_EXPECT' (it reads '$(sed -n 11p "$f")')."
  fi
done

for i in "${!APPR_PATH[@]}"; do
  f="${APPR_PATH[$i]}"; u="${APPR_UNIT[$i]}"; n="${APPR_LINE[$i]}"
  have="$(unit_key_above "$f" "$n" || true)"
  [ -n "$have" ] || refuse "$f:$n has no unit key above it; the list names unit '$u'."
  [ "$have" = "$u" ] || \
    refuse "$f:$n belongs to unit '$have', but the list names '$u'. The manifest moved under the reviewed line numbers; nothing was rewritten (SME decision D17-1)."
  if line_is "$f" "$n" "$UNIT_TARGET"; then continue; fi
  line_is "$f" "$n" "$UNIT_EXPECT" || \
    refuse "$f:$n is not '$UNIT_EXPECT' (it reads '$(sed -n "${n}p" "$f")')."
done

# --- pass 3: write ---------------------------------------------------------
for i in "${!ROOT_PATH[@]}"; do
  f="${ROOT_PATH[$i]}"
  if line_is "$f" 10 "$ROOT_BY_TARGET" && line_is "$f" 11 "$ROOT_AT_TARGET"; then continue; fi
  sed -i "10s|.*|$ROOT_BY_REPLACEMENT|; 11s|.*|$ROOT_AT_TARGET|" "$f"
  n_root=$((n_root + 1))
done

for i in "${!APPR_PATH[@]}"; do
  f="${APPR_PATH[$i]}"; n="${APPR_LINE[$i]}"
  if line_is "$f" "$n" "$UNIT_TARGET"; then continue; fi
  sed -i "${n}s|.*|$UNIT_TARGET|" "$f"
  n_unit=$((n_unit + 1))
done

# --- record the post-sign digest -------------------------------------------
# Appended once per manifest, on the first run that signs it. A later run reads
# it back and accepts the signed bytes, which is what keeps a re-run idempotent
# instead of a digest refusal.
for p in "${TOUCHED[@]}"; do
  if [ -z "$(recorded_for "$p" post)" ]; then
    printf 'digest-signed %s %s\n' "$p" "$(sha_of "$p")" >> "$LIST"
  fi
done

echo "sme_resign: $n_root root signature block(s) restored, $n_unit unit status line(s) approved (date $DATE)"
